import{_ as e,o,c as a,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"CC Switch 小白教程：3 分钟把 AI 中转站接进 Claude Code","description":"","frontmatter":{"title":"CC Switch 小白教程：3 分钟把 AI 中转站接进 Claude Code","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","Claude Code","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/01-小白教程.md","filePath":"guide/01-小白教程.md"}'),l={name:"guide/01-小白教程.md"};function d(s,t,r,n,c,u){return o(),a("div",null,[...t[0]||(t[0]=[i('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>这篇是给<strong>完全没碰过命令行的小白</strong>看的：教你用一个叫 CC Switch 的小工具，把自己的 AI 中转站（比如 ai.aklibk.com）接进 Claude Code，不用官方账号、不用绑海外卡，一个 API Key 就能用上 Claude、GPT 全家桶，而且想切回官方配置随时切，全程点点点，不用碰任何配置文件。</p><h2 id="一、先搞懂三件事-60-秒" tabindex="-1">一、先搞懂三件事（60 秒） <a class="header-anchor" href="#一、先搞懂三件事-60-秒" aria-label="Permalink to &quot;一、先搞懂三件事（60 秒）&quot;">​</a></h2><ul><li><strong>Claude Code</strong>：现在最火的 AI 编程助手，在终端里陪程序员写代码，你问它答，能帮你改代码、跑命令。</li><li><strong>AI 中转站</strong>：把 Claude、GPT、Gemini 这些国外模型的接口&quot;搬&quot;到国内能直接访问的地址。你不用注册官方账号、不用绑信用卡，在中转站充点钱、拿一个 Key，就能调用所有模型。</li><li><strong>CC Switch</strong>：一个电脑上的小工具，专门管理 Claude Code 这些 AI 工具的&quot;配置&quot;。以前换模型要手动改配置文件（小白看到 JSON 就头大），CC Switch 把它变成了<strong>点一下切换</strong>。</li></ul><p>一句话：<strong>CC Switch 就是 Claude Code 的&quot;遥控器&quot;，中转站就是&quot;电视信号源&quot;，遥控器一按就换台。</strong></p><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><p>（2 分钟）</p><p>只需要准备两样东西：</p><p><strong>① 一个中转站的 API Key</strong></p><ul><li>注册你的中转站账号（比如 ai.aklibk.com）</li><li>登录后台 → 找到 <strong>API Keys / 令牌</strong> 页面 → 创建新 Key</li><li>复制这串 <code>sk-</code> 开头的字符，先存记事本里，一会儿要粘</li></ul><p><strong>② 安装 Node.js</strong></p><ul><li>打开 <a href="https://nodejs.org/zh-cn" target="_blank" rel="noreferrer">https://nodejs.org/zh-cn</a> ，下载 <strong>LTS 版</strong>安装包</li><li>一路&quot;下一步&quot;装完（啥都不用改）</li><li>验证：按 <code>Win + R</code>，输入 <code>cmd</code> 回车，在弹出的黑窗口里输入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node --version</span></span></code></pre></div>看到 <code>v18</code> 或更高版本号就说明装好了</li></ul><h2 id="三、第一步-下载-cc-switch-1-分钟" tabindex="-1">三、第一步：下载 CC Switch（1 分钟） <a class="header-anchor" href="#三、第一步-下载-cc-switch-1-分钟" aria-label="Permalink to &quot;三、第一步：下载 CC Switch（1 分钟）&quot;">​</a></h2><ul><li>打开官网 <strong><a href="https://ccswitch.io" target="_blank" rel="noreferrer">https://ccswitch.io</a></strong>，或去 <strong>GitHub Releases</strong> 页面下载</li><li>⚠️ <strong>只从官网或官方 GitHub 下载！</strong> 网上任何要你付费、充值、登录的&quot;CC Switch&quot;网站都是山寨，千万别碰</li><li>Windows 用户选 <code>CC-Switch-v{版本号}-Windows-Portable.zip</code>（绿色版，免安装）</li><li>解压后双击 <code>CC-Switch.exe</code>，软件就打开了（任务栏会多个小图标）</li></ul><h2 id="四、第二步-把你的中转站加进去-1-分钟" tabindex="-1">四、第二步：把你的中转站加进去（1 分钟） <a class="header-anchor" href="#四、第二步-把你的中转站加进去-1-分钟" aria-label="Permalink to &quot;四、第二步：把你的中转站加进去（1 分钟）&quot;">​</a></h2><p>打开 CC Switch 主界面，按下面 6 步走：</p><ol><li>点右上角的 <strong>+</strong> 号，打开添加面板</li><li>选 <strong>Claude Code</strong>（给哪个工具用就选哪个，后面还能加 Codex/Gemini）</li><li>预设那里选 <strong>自定义</strong>（中转站都是自定义填参数）</li><li>填三个关键信息： <ul><li><strong>名称</strong>：随便写，比如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：填中转站给你的接口地址，例如 <code>https://ai.aklibk.com</code></li><li><strong>API Key</strong>：粘贴刚才复制的那串 <code>sk-</code> 开头的 Key</li></ul></li><li>点模型输入框旁边的 <strong>获取模型</strong> 按钮——CC Switch 会自动去中转站拉取可用模型列表，点选一个（比如 <code>claude-sonnet-4-5</code>）</li><li>点 <strong>添加</strong>，完事</li></ol><blockquote></blockquote><blockquote><p>小技巧：如果「获取模型」点不动或报 401，八成是 API 地址或 Key 填错了，回去检查一下。</p></blockquote><h2 id="五、第三步-切换并打开-claude-code-30-秒" tabindex="-1">五、第三步：切换并打开 Claude Code（30 秒） <a class="header-anchor" href="#五、第三步-切换并打开-claude-code-30-秒" aria-label="Permalink to &quot;五、第三步：切换并打开 Claude Code（30 秒）&quot;">​</a></h2><ol><li>在主界面找到刚添加的供应商，<strong>点一下它</strong>（选中 = 当前生效）</li><li>打开终端（Win+R → cmd），输入：<div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>claude</span></span></code></pre></div></li><li>出现对话界面</li></ol><blockquote></blockquote><p>，随便问一句&quot;你好&quot;——能回复就说明<strong>全部搞定！</strong></p><p><strong>想切回官方账号？</strong> 再点回原来的供应商（比如 Claude 官方）就行。CC Switch 自动帮你备份和切换配置文件，<strong>你永远不用手动碰配置文件</strong>。</p><h2 id="六、常见问题-救急用" tabindex="-1">六、常见问题（救急用） <a class="header-anchor" href="#六、常见问题-救急用" aria-label="Permalink to &quot;六、常见问题（救急用）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决方法</th></tr></thead><tbody><tr><td>报 401 / 连不上</td><td>API 地址或 Key 填错了，回去核对；地址结尾要不要 <code>/v1</code> 以中转站文档为准</td></tr><tr><td>拉不到模型列表</td><td>手动在模型框里填模型名（如 <code>claude-sonnet-4-5</code>）</td></tr><tr><td>下载的软件打不开</td><td>右键 → 属性 → 安全 → 勾选&quot;解除锁定&quot;</td></tr><tr><td>Claude Code 报错</td><td>终端运行 <code>claude doctor</code> 看诊断信息</td></tr><tr><td>用了中转站后想换模型</td><td>回 CC Switch 编辑供应商，换模型再切一次</td></tr></tbody></table><h2 id="七、总结" tabindex="-1">七、总结 <a class="header-anchor" href="#七、总结" aria-label="Permalink to &quot;七、总结&quot;">​</a></h2><p>三步走：<strong>下载 CC Switch → 填中转站地址和 Key → 点一下切换</strong>。就这么简单，全程不碰代码、不碰配置文件。</p><p>想要 Claude / GPT / Gemini 全家桶一个 Key 通吃、国内直连免绑卡、人民币按量付费？可以试试 Aklibk API 中转站（ai.aklibk.com），新用户充值还有优惠。</p><blockquote><p>下一篇预告：CC Switch 还能管 Codex 和 Gemini CLI，教你怎么一套配置三个工具随便切。</p></blockquote>',31)])])}const p=e(l,[["render",d]]);export{g as __pageData,p as default};
